   lines:[{s:"Receptionist",t:"Good morning, Parkside Sports Centre. How can I help you?"},{s:"Sarah",t:"Hi, I'm interested in joining. Could you tell me about the membership options?"},{s:"Receptionist",t:"Certainly. We have two main types. Standard membership is thirty-five pounds a month and gives you access to the gym and the swimming pool."},{s:"Sarah",t:"And the other one?"},{s:"Receptionist",t:"Premium membership is forty-eight pounds a month. That includes everything in standard, plus unlimited fitness classes and use of the sauna."},{s:"Sarah",t:"I'd mainly like to do yoga classes. How many are there each week?"},{s:"Receptionist",t:"Yoga runs four times a week: Monday and Wednesday evenings, and Saturday and Sunday mornings."},{s:"Sarah",t:"That's great. Is there a joining fee?"},{s:"Receptionist",t:"Normally it's twenty pounds, but this month there's no joining fee if you sign up for at least six months."},{s:"Sarah",t:"OK. I'll go for premium, then. What do I need to bring?"},{s:"Receptionist",t:"Just some photo ID and your bank details. Can I take your surname?"},{s:"Sarah",t:"It's Whitfield. W-H-I-T-F-I-E-L-D."}],
