window.COACH.listening.business.push({level:"C2",title:"A board-level disagreement",context:"You will hear two board members, Alicia and Peter, discussing a proposed acquisition.",speakers:{Alicia:"female",Peter:"male"},
 lines:[{s:"Alicia",t:"Before we vote, I want to put my reservations on record. The valuation of this acquisition rests on synergies that, frankly, look aspirational."},{s:"Peter",t:"Aspirational is a little harsh. The integration plan was stress-tested by two independent advisers."},{s:"Alicia",t:"Stress-tested against assumptions we supplied. That's rather like marking your own homework."},{s:"Peter",t:"Fair point, though I'd note that doing nothing isn't risk-free either. If a competitor acquires them, we'll be at a significant disadvantage in that market."},{s:"Alicia",t:"I don't dispute the strategic logic. My concern is the price. We're paying a premium of nearly forty per cent, and our track record with integrations is, let's say, uneven."},{s:"Peter",t:"So you'd support the deal at a lower price?"},{s:"Alicia",t:"I'd support it with an earn-out — part of the payment tied to performance over three years. That way, if the synergies materialise, the sellers are rewarded; if they don't, we're protected."},{s:"Peter",t:"The sellers may walk away."},{s:"Alicia",t:"Then we'll have learned how confident they really are in their own forecasts."}],
 questions:[{q:"What is Alicia's main concern?",options:["The strategic logic","The price and over-optimistic synergies","The advisers' fees","The competitor's size"],answer:1,explain:"Synergies look aspirational; the premium is high."},
  {q:"What does \"marking your own homework\" suggest?",options:["The tests were independent","The tests used the company's own assumptions, so they aren't reliable","The advisers were students","The plan is finished"],answer:1,explain:"The stress tests relied on assumptions the company supplied."},
  {q:"What risk does Peter mention of not buying?",options:["Losing staff","A competitor might buy them instead","Higher taxes","Lower share price"],answer:1,explain:"If a competitor acquires them, they'd be at a disadvantage."},
  {q:"What does Alicia propose?",options:["Cancelling the deal","An earn-out linking payment to future performance","Paying a higher price","Hiring new advisers"],answer:1,explain:"Part of the payment tied to performance over three years."},
  {q:"What does Alicia's final remark imply?",options:["She hopes the sellers leave","The sellers' reaction will reveal their true confidence","She will resign","The forecasts are accurate"],answer:1,explain:"If they walk away, it shows they doubt their own forecasts."}]});
window.COACH.listening.ielts.unshift({level:"A2",title:"IELTS foundation: Booking a bus ticket",context:"You will hear a man, Ken, buying a bus ticket. You will hear the recording TWICE (foundation level).",speakers:{Clerk:"female",Ken:"male"},
 lines:[{s:"Clerk",t:"Hello, City Bus Station. How can I help?"},{s:"Ken",t:"Hi. I want a ticket to Baguio, please."},{s:"Clerk",t:"For which day?"},{s:"Ken",t:"Next Tuesday, in the morning."},{s:"Clerk",t:"There's a bus at seven fifteen and one at nine thirty."},{s:"Ken",t:"Nine thirty, please. How much is it?"},{s:"Clerk",t:"It's four hundred and fifty pesos for one way."},{s:"Ken",t:"OK. One way, please."},{s:"Clerk",t:"Can I have your name?"},{s:"Ken",t:"Ken Santos. S-A-N-T-O-S."},{s:"Clerk",t:"Thank you. Please come thirty minutes before the bus leaves."}],
 questions:[{q:"Where does Ken want to go?",options:["Manila","Baguio","Cebu","Davao"],answer:1,explain:"\"A ticket to Baguio.\""},
  {q:"Which day does he want to travel?",options:["Monday","Tuesday","Thursday","Saturday"],answer:1,explain:"\"Next Tuesday.\""},
  {q:"What time is his bus?",options:["7:15","7:30","9:15","9:30"],answer:3,explain:"He chooses nine thirty."},
  {q:"How much is the ticket?",options:["₱400","₱450","₱540","₱900"],answer:1,explain:"Four hundred and fifty pesos."},
  {q:"When should Ken arrive at the station?",options:["10 minutes before","15 minutes before","30 minutes before","1 hour before"],answer:2,explain:"\"Thirty minutes before the bus leaves.\""}]});
window.COACH.listening.ielts.push({level:"C2",title:"Section 4: The economics of attention",context:"You will hear part of an academic talk, followed by a question from a student. You will hear the recording ONCE.",speakers:{Lecturer:"female",Student:"male"},
 lines:[{s:"Lecturer",t:"Today I want to examine what economists have termed the attention economy. The central premise is deceptively simple: in an environment of informational abundance, the scarce resource is not information but the human capacity to attend to it."},{s:"Lecturer",t:"Herbert Simon anticipated this as early as 1971, observing that a wealth of information creates a poverty of attention. What he could not have foreseen is the extent to which firms would compete — with considerable sophistication — to capture and monetise that attention."},{s:"Lecturer",t:"Now, one consequence that is frequently overlooked is distributional. Those with the resources to purchase uninterrupted time — through ad-free subscriptions, for instance — effectively buy back their attention, whereas others pay with it."},{s:"Lecturer",t:"Regulatory responses have so far focused on privacy, which, while important, addresses only part of the problem. A more radical proposal treats attention itself as something deserving protection, analogous to environmental resources."},{s:"Student",t:"Excuse me — wouldn't that be almost impossible to measure, let alone regulate?"},{s:"Lecturer",t:"It's a fair objection, and measurement is certainly the weakest link in the argument. But we regulated pollution long before we could measure every pollutant precisely. The difficulty of measurement is a reason for caution, not for inaction."}],
 questions:[{q:"According to the talk, what is scarce in the attention economy?",options:["Information","Human attention","Technology","Advertising"],answer:1,explain:"\"The scarce resource is… the capacity to attend to it.\""},
  {q:"What did Herbert Simon NOT foresee?",options:["Information abundance","A poverty of attention","How firms would compete to monetise attention","The internet's speed"],answer:2,explain:"He couldn't foresee firms competing to capture attention."},
  {q:"What is the \"distributional\" consequence mentioned?",options:["Wealthier people can buy back their attention; others pay with it","Everyone pays the same","Firms lose money","Regulation is equal for all"],answer:0,explain:"Ad-free subscriptions let some buy back attention."},
  {q:"What does the student object to?",options:["Privacy laws","The difficulty of measuring and regulating attention","Herbert Simon's theory","Subscription prices"],answer:1,explain:"\"Almost impossible to measure, let alone regulate.\""},
  {q:"How does the lecturer answer the objection?",options:["She agrees regulation is pointless","She compares it to pollution, regulated before precise measurement","She changes the topic","She says measurement is easy"],answer:1,explain:"\"We regulated pollution long before we could measure every pollutant.\""}]});
